export interface Coin {
  denom: string;
  amount: string;
}

export interface AccountState {
  balance: Coin;
  nonce: string;
}

export interface Validator {
  operatorAddress: string;
  consensusPubKey: string;
  jailed: boolean;
  status: number;
  tokens: string;
  delegatorShares: string;
  moniker: string;
  website: string;
  details: string;
}

export interface Delegation {
  delegatorAddress: string;
  validatorAddress: string;
  shares: string;
}

export interface StakePot {
  totalWeight: string;
  rewardPerBlock: string;
}

export interface DelegatorReward {
  amount: Coin;
}

export interface VaultBalances {
  onStake: Coin;
  onMarket: Coin;
  deposited: Coin;
}

export interface TokenInfo {
  chainId: string;
  address: string;
  symbol: string;
  decimals: number;
}

export interface Tenant {
  owner: string;
  name: string;
}

export interface ChainConfig {
  chainId: string;
  minStake: string;
  minDelegate: string;
  rewardPerBlock: string;
  unbondingPeriod: string;
}

export interface AttestSchema {
  uid: string;
  schema: string;
  resolver: string;
  revocable: boolean;
}

export interface Attestation {
  uid: string;
  schemaUID: string;
  attester: string;
  recipient: string;
  revoked: boolean;
  expirationTime: string;
  data: string;
}

export interface AttestVerifyResult {
  valid: boolean;
  uid: string;
  checks: string[];
}

export interface DecodedParameter {
  name: string;
  type: string;
  value: unknown;
}

export interface DecodedInput {
  functionName: string;
  parameters: DecodedParameter[];
}

export interface SyncStatus {
  lastIndexedBlock: number;
  lastStateSyncedBlock: number;
}

export interface Sentry {
  id: string;
  owner: string;
  pubKey: string;
  status: string;
}

export interface ValidatorPlatformInfo {
  address: string;
  moniker: string;
  website: string;
}

export interface SentryApplication {
  id: string;
  sentryId: string;
  validator: string;
  status: string;
}

export interface Assignment {
  id: string;
  sentryId: string;
  validator: string;
  chainId: string;
}

export interface TxWatchRequest {
  txHash: string;
  domain: 'stake' | 'attest' | 'platform';
}

export interface EntityChange {
  kind: string;
  uid: string;
  action: 'UPSERT' | 'DELETE';
}

export interface TxWatchReady {
  type: 'ready';
  txHash: string;
  domain: string;
  blockNumber: number;
  receiptStatus: boolean;
  changes: EntityChange[];
}

export interface TxWatchTimeout {
  type: 'timeout';
  txHash: string;
  domain: string;
}

export interface TxWatchError {
  type: 'error';
  txHash?: string;
  domain?: string;
  message: string;
}

export type TxWatchMessage = TxWatchReady | TxWatchTimeout | TxWatchError;

export interface NewBlockMessage {
  type: 'newBlock';
  block: {
    jsonrpc: string;
    id: string;
    result: {
      query: string;
      data: {
        type: string;
        value: {
          block: {
            header: {
              version: { block: string };
              chain_id: string;
              height: string;
              time: string;
              last_block_id: { hash: string; parts: { total: number; hash: string } };
              last_commit_hash: string;
              data_hash: string;
              validators_hash: string;
              next_validators_hash: string;
              consensus_hash: string;
              app_hash: string;
              last_results_hash: string;
              evidence_hash: string;
              proposer_address: string;
            };
            data: { txs: string[] | null };
            evidence: { evidence: unknown[] };
            last_commit: unknown;
          };
          result_begin_block: unknown;
          result_end_block: unknown;
        };
      };
      events: Record<string, string[]>;
    };
  };
}

export interface JsonRpcRequest {
  jsonrpc: '2.0';
  method: string;
  params: unknown[];
  id: number;
}

export interface JsonRpcResponse<T = unknown> {
  jsonrpc: '2.0';
  id: number;
  result?: T;
  error?: {
    code: number;
    message: string;
    data?: string;
  };
}

export interface EthereumBlock {
  number: string;
  hash: string;
  parentHash: string;
  nonce: string;
  sha3Uncles: string;
  logsBloom: string;
  transactionsRoot: string;
  stateRoot: string;
  receiptsRoot: string;
  miner: string;
  difficulty: string;
  totalDifficulty: string;
  extraData: string;
  size: string;
  gasLimit: string;
  gasUsed: string;
  timestamp: string;
  transactions: string[] | unknown[];
  uncles: string[];
  baseFeePerGas?: string;
}

export interface EthereumTransaction {
  blockHash: string;
  blockNumber: string;
  from: string;
  gas: string;
  gasPrice: string;
  hash: string;
  input: string;
  nonce: string;
  to: string;
  transactionIndex: string;
  value: string;
  v: string;
  r: string;
  s: string;
}

export interface EthereumTransactionReceipt {
  blockHash: string;
  blockNumber: string;
  contractAddress: string | null;
  cumulativeGasUsed: string;
  from: string;
  gasUsed: string;
  logs: unknown[];
  logsBloom: string;
  status: string;
  to: string;
  transactionHash: string;
  transactionIndex: string;
}

export interface GrphClientConfig {
  baseUrl: string;
  rpc: boolean;
  ws: {
    txWatch: boolean;
    blocks: boolean;
  };
  reconnect: {
    enabled: boolean;
    maxRetries: number;
    baseDelayMs: number;
    maxDelayMs: number;
  };
}

const DEFAULT_CONFIG: GrphClientConfig = {
  baseUrl: 'http://localhost:3003/graphene-evm',
  rpc: true,
  ws: {
    txWatch: true,
    blocks: true,
  },
  reconnect: {
    enabled: true,
    maxRetries: 10,
    baseDelayMs: 1000,
    maxDelayMs: 30000,
  },
};

export function defaultConfig(): GrphClientConfig {
  return { ...DEFAULT_CONFIG };
}
